public class Lesson {
    public static void main(String[] args) {
        int found = 0;
        for (int dz = 1; dz <= 5; dz++) {
            String block = Playground.getBlock(0, -1, dz);
            System.out.println(dz + " blocks ahead, standing on: " + block);
            if (!block.equals("air")) {
                found++;
            }
        }

        if (found == 5) {
            Playground.say("Solid ground the whole way -- nice.");
            Playground.particles(0, 1, 3, "happy_villager", 20);
            Playground.giveItem("emerald", 1);
        } else {
            Playground.say("Watch out, there's a gap up ahead!");
            Playground.particles(0, 1, 3, "flame", 20);
        }
    }
}
